program.# The query buttons on their panel. Each:
# Paneldagi soʻrov tugmalari. Har biri skrinshotni Google’ga yuboradi:
#   name: tugmaning maslahati;
#   mode: skrinshot qayerga ketadi:
#     "ai": Google SI rasm va savol boʻyicha natijalar ustida mini-promptga soʻz bilan
#       javob beradi;
#     "chat": dastur oynasidagi AI Mode (google.com/ai): dastur skrinshot va savolni u yerga
#       qoʻyadi va yuboradi; oyna ajratilgan soha yonida chiqadi, unda faqat suhbat va keyingi
#       savol maydoni boʻladi; tugma bosib turilganda mini-prompt oʻrniga oʻz savolingizni
#       ovoz bilan berasiz;
#     "answer": xuddi shunday, lekin oyna yashirin: javob ajratilgan soha yonidagi
#       kartochkada chiqadi;
#     "images": savolsiz rasm boʻyicha qidiruv, dastur oynasida ajratilgan soha yonida:
#       darhol aniq mosliklar, yaʼni aynan shu rasm bor sahifalar; ularning sarlavhalarida
#       rasmda kim yoki nima borligi koʻpincha yoziladi;
#   prompt: mini-prompt, SIga savol, "ai", "chat" va "answer" uchun;
#   key: ekran muzlatilgan paytdagi tugma klavishi;
#   icon: "google", "translate", "images" yoki "question".
# Panelda avval SI tugmalari, ulardan keyin rasm boʻyicha qidiruv turadi.
# Google’ga dastur oynasida, sozlamalar oynasining “Google hisobi” boʻlimidan kiriladi;
# hech kim kirmagan boʻlsa, dastur ishga tushganda kirishni taklif qiladi.

program.# Install new versions by itself. The pr:
# Yangi versiyalarni avtomatik oʻrnatish. Dastur ishga tushganda va kuniga bir marta
# yangi versiyani qidiradi hamda oynalaridan hech biri ochiq boʻlmaganda uni oʻrnatadi;
# false boʻlsa, yangi versiyani faqat sozlamalar oynasida va treydagi belgi menyusida koʻrsatadi.
